/**
 * Typed access to the Apple Health outputs generated by
 * `PYTHONPATH=src python -m apple_health demo` (see projects/apple-health-analytics).
 * Components read numbers from here; no metric value is typed by hand.
 */

import summaryJson from "./generated/apple-health/summary.json";
import weeklyJson from "./generated/apple-health/weekly.json";

export type MetricGroup = "activity" | "cardio" | "mobility" | "environment";

export type MetricMeta = {
  key: string;
  label: string;
  unit: string;
  aggregation: "sum" | "mean" | "energy_mean" | "last" | "stood_hours";
  group: MetricGroup;
};

export type Kpi = {
  key: string;
  group: MetricGroup;
  label: string;
  value: number | null;
  unit: string;
  definition: string;
};

export type QualityMetric = {
  metric: string;
  label: string;
  records: number;
  units: Record<string, number>;
  devices: Record<string, number>;
  out_of_range: number;
  day_coverage: number;
  aggregation: MetricMeta["aggregation"];
};

export type Summary = {
  synthetic: boolean;
  notice: string;
  generator: { seed: number; records: number; days: number };
  period: { start: string; end: string; days: number };
  metrics: MetricMeta[];
  kpis: Kpi[];
  quality: {
    records_total: number;
    metrics_present: number;
    checks: {
      exact_duplicates: number;
      unit_rejected: number;
      unit_converted: number;
      out_of_range: number;
      negative_duration: number;
      overlap_records_removed: number;
      days_without_watch_data: number | null;
    };
    by_metric: QualityMetric[];
    transform: { overlap_by_metric: Record<string, number> };
  };
  aggregation_audit: {
    resting_hr: {
      days: number;
      days_with_multiple_estimates: number;
      max_implicit_sum: number;
      max_daily_mean: number;
      march_comparison: { date: string; implicit_sum: number | null; daily_mean: number | null }[];
    };
    steps: { avg_naive_sum: number; avg_deduplicated: number; inflation_pct: number };
    environmental_audio: { avg_daily_gap_db: number; max_daily_gap_db: number };
  };
};

export type SeriesRow = Record<string, number | string | null> & { [key: string]: unknown };

export const summary = summaryJson as unknown as Summary;
export const weekly = (weeklyJson as unknown as { rows: SeriesRow[] }).rows;

export const metricByKey = Object.fromEntries(summary.metrics.map((m) => [m.key, m])) as Record<
  string,
  MetricMeta
>;

export const kpiByKey = Object.fromEntries(summary.kpis.map((k) => [k.key, k])) as Record<string, Kpi>;
